    if not token or token.count(".") < 2:
        return {}
    try:
        payload_b64 = token.split(".", 2)[1]
        payload_b64 += "=" * (-len(payload_b64) % 4)
        data = json.loads(base64.urlsafe_b64decode(payload_b64.encode()).decode())
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}

