def flush_code():
        """Flush accumulated code as a code block."""
        nonlocal code_buffer
        # Strip leading/trailing empty lines from code buffer
        while code_buffer and not code_buffer[0].strip():
            code_buffer.pop(0)
        while code_buffer and not code_buffer[-1].strip():
            code_buffer.pop()

        if code_buffer:
            last_nonempty = next((l for l in reversed(result) if l.strip()), None)
            if last_nonempty is not None and last_nonempty.rstrip().endswith('::'):
                pass  # preceding text already ends with ::
            else:
                result.append('::')
                result.append('')
            for line in code_buffer:
                result.append('    ' + line if line.strip() else '')
            result.append('')
        code_buffer = []

