def _discover_and_add_sitemap_urls(self, url):
    """Discover and add sitemap URLs from the given URL"""
    try:
        # Parse the URL
        parsed = urlparse(url)
        base_domain = parsed.netloc
        base_url = f"{parsed.scheme}://{parsed.netloc}"

        # Check if sitemap is already added
        if self.sitemap_urls:
            if base_domain in self.sitemap_urls:
                return

        # Discover sitemaps
        sitemap_urls = self._discover_sitemaps(base_domain)
        if not sitemap_urls:
            return

        # Add sitemap URLs to the link manager
        for sitemap_url in sitemap_urls:
            if sitemap_url.startswith('http'):
                self.link_manager.add_url(sitemap_url, 0)
                self.stats['discovered'] += 1
                print(f"Added sitemap: {sitemap_url}")
    except Exception as e:
        print(f"Error discovering sitemaps: {str(e)}")

