    out_type = type(data)
    if out_type is list:
        return result
    try:
        if issubclass(out_type, tuple) and hasattr(out_type, "_fields"):
            return out_type(*result)
        return out_type(result)
    except TypeError:
        return list(result) if issubclass(out_type, list) else tuple(result)

