def _write_incomplete_warning(
    terminalreporter: TerminalReporter,
    rampart_session: RampartSession,
) -> None:
    """Write an incomplete-run warning if the session is not complete."""
    if rampart_session.is_incomplete:
        terminalreporter.write_line(
            f"Warning: Incomplete run detected. "
            f"RAMPART may not have captured all test results.",
            severity=WarningSeverity.INCOMPLETE,
        )

def _write_result_line(
    terminalreporter: TerminalReporter,
    result: RampartResult,
    test_name: str,
) -> None:
    """Write a line for a single RampartResult."""
    status = result.status
    if status == SafetyStatus.ERROR:
        terminalreporter.write_line(
            f"{test_name} - {result.message}",
            severity=Severity.ERROR,
        )
    elif status == SafetyStatus.UNSAFE:
        terminalreporter.write_line(
            f"{test_name} - {result.message}",
            severity=Severity.HARMFUL,
        )
    elif status == SafetyStatus.UNDETERMINED:
        terminalreporter.write_line(
            f"{test_name} - {result.message}",
            severity=Severity.INFORMATIONAL,
        )
    elif status == SafetyStatus.SAFE:
        terminalreporter.write_line(
            f"{test_name} - {result.message}",
            severity=Severity.INFORMATIONAL,
        )
    else:
        terminalreporter.write_line(
            f"{test_name} - {result.message}",
            severity=Severity.INFORMATIONAL,
        )

