) -> None:
    """Write trial group lines for the session."""
    trial_groups = rampart_session.trial_groups
    for trial_group in trial_groups:
        if trial_group.is_incomplete:
            terminalreporter.write_line(
                f"Trial Group: {trial_group.name} - Incomplete",
